export default {
  data: function data() {
    return {
      orderId: null,
      order: null,
      reviewForm: {
        orderId: null,
        idleId: null,
        rating: 5,
        content: ''
      },
      rules: {
        content: [{
          required: true,
          message: '请填写评价内容',
          trigger: 'blur'
        }, {
          min: 5,
          max: 500,
          message: '长度在 5 到 500 个字符',
          trigger: 'blur'
        }]
      },
      loading: false
    };
  },
  created: function created() {
    this.orderId = this.$route.query.orderId;
    if (this.orderId) {
      this.getOrderInfo();
      this.checkReviewExists();
    } else {
      this.$message.error('订单ID不存在');
      this.goBack();
    }
  },
  methods: {
    // 获取订单信息
    getOrderInfo: function getOrderInfo() {
      var _this = this;
      this.loading = true;
      this.$api.getOrder({
        id: this.orderId
      }).then(function (res) {
        if (res.status_code === 1) {
          _this.order = res.data;
          _this.reviewForm.orderId = _this.orderId;
          // 保存商品ID以便评价使用
          _this.reviewForm.idleId = _this.order.idleId;
        } else {
          _this.$message.error(res.msg || '获取订单信息失败');
          _this.goBack();
        }
      }).catch(function (err) {
        console.error('获取订单信息失败', err);
        _this.$message.error('订单获取失败');
      }).finally(function () {
        _this.loading = false;
      });
    },
    // 检查是否已经评价过
    checkReviewExists: function checkReviewExists() {
      var _this2 = this;
      this.$api.getIdleReviews({
        orderId: this.orderId
      }).then(function (res) {
        if (res.status_code === 1 && res.data && res.data.length > 0) {
          _this2.$message.warning('您已经评价过该订单');
          _this2.$router.push({
            path: '/orders'
          });
        }
      }).catch(function (err) {
        console.error('检查评价失败', err);
      });
    },
    // 提交评价
    submitReview: function submitReview() {
      var _this3 = this;
      this.$refs.reviewForm.validate(function (valid) {
        if (valid) {
          _this3.loading = true;
          _this3.$api.addReview(_this3.reviewForm).then(function (res) {
            if (res.status_code === 1) {
              _this3.$message.success('评价成功');
              _this3.$router.push({
                path: '/me'
              });
            } else {
              _this3.$message.error(res.msg || '评价失败');
            }
          }).catch(function (err) {
            console.error('评价失败', err);
            _this3.$message.error('评价失败，请重试');
          }).finally(function () {
            _this3.loading = false;
          });
        }
      });
    },
    // 返回订单列表
    goBack: function goBack() {
      this.$router.push({
        path: '/me'
      });
    },
    // 格式化时间
    formatTime: function formatTime(time) {
      if (!time) return '无';
      return new Date(time).toLocaleString();
    }
  }
};
